// MapController.ts
import { _decorator, Component, Node, SpriteFrame, assetManager, view, Size, Vec3, AssetManager } from 'cc';
import { MapModel } from './MapModel';
import { MapView } from './MapView';
import { MapData } from './MapData';
import { HexagonLayout } from '../Enums/TileEnums';
import { Tile } from '../Tiles/Tile'; // 新增导入
import { HexagonSpriteConfig } from '../Configs/HexagonSpriteConfig';

const { ccclass, property } = _decorator;

@ccclass('MapController')
export class MapController extends Component {
    @property({ type: HexagonLayout, tooltip: '六边形排列方式' })
    layout: HexagonLayout = HexagonLayout.Horizontal; // 默认水平排列

    @property({ type: Tile, tooltip: 'Tile 配置组件' })
    tile: Tile | null = null; // 用于在编辑器中拖拽赋值

    private model: MapModel;
    private view: MapView;
    private mapData: MapData;

    start() {
        // 获取六边形尺寸（优先使用外部 Tile，否则使用默认值）
        const hexWidth = this.tile?.hexWidth ?? 120;
        const hexHeight = this.tile?.hexHeight ?? 140;

        // 初始化各模块并传入 hex 宽高
        this.mapData = new MapData(this.layout, hexWidth, hexHeight);
        this.model = new MapModel(this.layout);
        this.view = new MapView(this.node);

        // 初始化 tileMap 数组
        this.initializeTileMap();

        // 加载资源
        this.loadResources().then(() => {
            // 获取屏幕尺寸并转换为 Vec3
            const screenSize: Size = view.getVisibleSize();
            const screenSizeVec3 = new Vec3(screenSize.width, screenSize.height, 0);

            // 计算行列数
            const { cols, rows } = this.mapData.calculateLayout(screenSizeVec3);

            // 生成六边形节点，将 hex 宽高传入 generateHexagons
            this.view.generateHexagons(this.model, cols, rows, this.layout, hexWidth, hexHeight);
        }).catch(err => {
            console.error('资源加载失败:', err);
        });
    }

    private initializeTileMap() {
        const cols = 10; // 假设列数为 10
        const rows = 10; // 假设行数为 10

        this.model.initializeTileMap(cols, rows);
    }

    private async loadResources(): Promise<SpriteFrame[]> {
        const bundleName = 'Images';
        const terrainType = 'Dirt'; // 可通过配置或外部传入切换为 Grass、Stone 等

        // 获取 SpriteFrame 路径列表（来自 JSON 或 TS 配置）
        const spriteFramePaths = HexagonSpriteConfig.getTerrainFrames(terrainType);

        // 异步加载资源
        const spriteFrames: SpriteFrame[] = [];

        try {
            const bundle = await new Promise<AssetManager.Bundle>((resolve, reject) => {
                assetManager.loadBundle(bundleName, (err, bundle) => {
                    if (err) reject(err);
                    else resolve(bundle);
                });
            });

            for (const path of spriteFramePaths) {
                const frame = await new Promise<SpriteFrame>((resolve, reject) => {
                    bundle.load(path, SpriteFrame, (err, spriteFrame) => {
                        if (err) reject(err);
                        else resolve(spriteFrame);
                    });
                });

                spriteFrames.push(frame);
            }

            this.model.setSpriteFrames(spriteFrames);
            return spriteFrames;
        } catch (err) {
            console.error('资源加载失败:', err);
            throw err;
        }
    }
}